(function(root){
function create(exchange,symbol,mode='scalp'){return {exchange,symbol,mode,revision:0,source:'empty',entry:'',stop:'',target:'',side:1,confirmed:false,expires:0,cleared:false};}
function edit(d,fields){return {...d,...fields,revision:d.revision+1,source:'manual',strategyContext:fields.side!==undefined&&+fields.side!==d.side?null:d.strategyContext,confirmed:true,expires:0,cleared:false};}
function roundPrice(value,tick){let n=Number(value);if(!(Number.isFinite(tick)&&tick>0))return n;return Number((Math.round(n/tick)*tick).toFixed(Math.min(12,Math.max(0,Math.ceil(-Math.log10(tick)))+2)))}
function strategy(d,p,at,expires,tick){if(!p)return {...create(d.exchange,d.symbol,d.mode),revision:d.revision+1};return {...d,surge:false,entry:roundPrice(p.entry,tick),stop:roundPrice(p.stop,tick),target:roundPrice(p.target,tick),side:p.side,confirmed:!!p.confirmed,expires,signalAt:at,revision:d.revision+1,source:'strategy',strategyContext:{mode:d.mode,level:p.level??p.trigger??p.entry,signalAt:at},cleared:false};}
function plan(d){if(!d||d.cleared)return null;let entry=+d.entry,stop=+d.stop,target=+d.target,side=+d.side;if(![entry,stop,target].every(x=>Number.isFinite(x)&&x>0)||![1,-1].includes(side)||side*(entry-stop)<=0||side*(target-entry)<=0)return null;return {entry,stop,target,side,risk:side*(entry-stop),confirmed:d.confirmed,manual:d.source==='manual',mode:d.mode};}
function gate(d,{now=Date.now(),quoteAt=0,connected=false,accountAt=0,rules=false,demo=false,exchange,symbol,price}={}){if(d&&((exchange&&d.exchange!==exchange)||(symbol&&d.symbol!==symbol)))return 'Wait for the selected coin to finish loading.';if(!plan(d))return 'Set entry, stop and target to see your plan on the chart.';if(demo)return null;if(d.source==='strategy'&&!d.confirmed)return 'Forming setup — wait for the required candle close.';if(d.source==='strategy'&&d.expires&&now>d.expires)return 'This strategy plan has expired. Load a fresh setup.';if(d.source==='strategy'&&Number.isFinite(price)){if(d.side*(price-Number(d.stop))<=0)return 'This setup has breached its stop. Load a fresh setup.';if(d.side*(price-Number(d.target))>=0)return 'This setup has already reached its target. Load a fresh setup.';}if(!connected)return 'Connect your account in Settings before trading.';if(!quoteAt||now-quoteAt>15000||quoteAt>now+1000)return 'Market data is stale. Wait for a fresh price before trading.';if(!accountAt||now-accountAt>30000||accountAt>now+1000)return 'Account balance is stale. Refresh your account in My Positions.';if(!rules)return 'Contract limits are unavailable. Reload this coin.';return null;}
function accepted(d,context){if(!d||!context||context.action!=='open'||context.exchange!==d.exchange||context.symbol!==d.symbol||context.revision!==d.revision)return d;return {...create(d.exchange,d.symbol,d.mode),revision:d.revision+1,cleared:true};}
root.CustomerFlow={roundPrice,create,edit,strategy,plan,gate,accepted};
})(typeof window==='undefined'?globalThis:window);
